example:
// bynk.toml
[deploy.workers.core]
contexts = ["shop.orders", "shop.billing"]

// shop/orders.bynk
asset terms = "assets/orders-terms.txt" at "/terms.txt"

// shop/billing.bynk
asset terms = "assets/billing-terms.txt" at "/terms.txt"           // ✗ `shop.orders` serves `/terms.txt`
asset terms = "assets/billing-terms.txt" at "/billing/terms.txt"   // ✓
